import { useState } from 'react'
import {
  startRegistration,
  startAuthentication,
} from '@simplewebauthn/browser'

const API_BASE = '/api'

export function Enroll() {
  const [code, setCode] = useState('')
  const [status, setStatus] = useState<string>('')
  const [error, setError] = useState<string>('')

  const enroll = async () => {
    setStatus('Beginning enrollment…')
    setError('')

    try {
      const beginResp = await fetch(`${API_BASE}/auth/enroll/begin`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code }),
      })
      if (!beginResp.ok) {
        const data = await beginResp.json().catch(() => ({ detail: beginResp.statusText }))
        throw new Error(data.detail || `HTTP ${beginResp.status}`)
      }
      const options = await beginResp.json()

      setStatus('Waiting for authenticator…')
      const attResp = await startRegistration({ optionsJSON: options })

      setStatus('Verifying…')
      const verifyResp = await fetch(`${API_BASE}/auth/enroll/verify`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ credential: attResp }),
      })
      if (!verifyResp.ok) {
        const data = await verifyResp.json().catch(() => ({ detail: verifyResp.statusText }))
        throw new Error(data.detail || `HTTP ${verifyResp.status}`)
      }

      const result = await verifyResp.json()
      setStatus(`Enrolled as ${result.user_id}`)
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e))
      setStatus('')
    }
  }

  return (
    <section className="bg-white rounded-lg shadow p-4">
      <h2 className="text-sm font-medium text-gray-600 mb-2">Enroll Device (WebAuthn)</h2>
      <p className="text-xs text-gray-500 mb-3">
        Enter your enrollment code to register a new authenticator.
      </p>
      <div className="flex gap-2">
        <input
          type="text"
          value={code}
          onChange={(e) => setCode(e.target.value)}
          placeholder="Enrollment code"
          className="flex-1 border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
        <button
          onClick={enroll}
          disabled={!code.trim()}
          className="bg-blue-600 text-white rounded-lg px-4 py-2 text-sm font-medium hover:bg-blue-700 disabled:opacity-50"
        >
          Enroll
        </button>
      </div>
      {status && <p className="mt-2 text-sm text-blue-600">{status}</p>}
      {error && <p className="mt-2 text-sm text-red-600">{error}</p>}
    </section>
  )
}

export function SignIn() {
  const [status, setStatus] = useState<string>('')
  const [error, setError] = useState<string>('')
  const [signedIn, setSignedIn] = useState(false)

  const signIn = async () => {
    setStatus('Beginning login…')
    setError('')

    try {
      const beginResp = await fetch(`${API_BASE}/auth/login/begin`, {
        method: 'POST',
      })
      if (!beginResp.ok) {
        const data = await beginResp.json().catch(() => ({ detail: beginResp.statusText }))
        throw new Error(data.detail || `HTTP ${beginResp.status}`)
      }
      const options = await beginResp.json()

      setStatus('Waiting for authenticator…')
      const asseResp = await startAuthentication({ optionsJSON: options })

      setStatus('Verifying…')
      const verifyResp = await fetch(`${API_BASE}/auth/login/verify`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ assertion: asseResp }),
      })
      if (!verifyResp.ok) {
        const data = await verifyResp.json().catch(() => ({ detail: verifyResp.statusText }))
        throw new Error(data.detail || `HTTP ${verifyResp.status}`)
      }

      const result = await verifyResp.json()
      setStatus(`Signed in as ${result.user_id}`)
      setSignedIn(true)
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e))
      setStatus('')
    }
  }

  const signOut = async () => {
    await fetch(`${API_BASE}/auth/logout`, { method: 'POST' })
    setStatus('')
    setSignedIn(false)
  }

  return (
    <section className="bg-white rounded-lg shadow p-4">
      <h2 className="text-sm font-medium text-gray-600 mb-2">Sign In (WebAuthn)</h2>
      {signedIn ? (
        <button
          onClick={signOut}
          className="bg-gray-600 text-white rounded-lg px-4 py-2 text-sm font-medium hover:bg-gray-700"
        >
          Sign Out
        </button>
      ) : (
        <button
          onClick={signIn}
          className="bg-blue-600 text-white rounded-lg px-4 py-2 text-sm font-medium hover:bg-blue-700"
        >
          Sign In
        </button>
      )}
      {status && <p className="mt-2 text-sm text-blue-600">{status}</p>}
      {error && <p className="mt-2 text-sm text-red-600">{error}</p>}
    </section>
  )
}

import { useState } from 'react'
import { startAuthentication } from '@simplewebauthn/browser'

const API_BASE = '/api'

interface AuthzData {
  authorization_id: string
  bundle_id: string
  operation: string
  status: string
  envelope_hash: string
  issued_at: string
  expires_at: string
  conversation_id: string | null
}

export function Approve() {
  const [authzId, setAuthzId] = useState('')
  const [authz, setAuthz] = useState<AuthzData | null>(null)
  const [status, setStatus] = useState('')
  const [error, setError] = useState('')

  const fetchAuthz = async () => {
    setStatus('')
    setError('')
    try {
      const resp = await fetch(`${API_BASE}/authorizations/${authzId}`)
      if (!resp.ok) {
        const data = await resp.json().catch(() => ({ detail: resp.statusText }))
        throw new Error(data.detail || `HTTP ${resp.status}`)
      }
      setAuthz(await resp.json())
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e))
    }
  }

  const approve = async () => {
    if (!authz) return
    setStatus('Beginning approval…')
    setError('')

    try {
      // Begin login to get assertion options (challenge).
      const beginResp = await fetch(`${API_BASE}/auth/login/begin`, {
        method: 'POST',
      })
      if (!beginResp.ok) {
        throw new Error(`Login begin failed: HTTP ${beginResp.status}`)
      }
      const loginOptions = await beginResp.json()

      setStatus('Waiting for authenticator…')
      const asseResp = await startAuthentication({ optionsJSON: loginOptions })

      setStatus('Submitting approval…')
      const resp = await fetch(
        `${API_BASE}/authorizations/${authz.authorization_id}/approve`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            authorization_id: authz.authorization_id,
            expected_envelope_hash: authz.envelope_hash,
            assertion: asseResp,
          }),
        },
      )
      if (!resp.ok) {
        const data = await resp.json().catch(() => ({ detail: resp.statusText }))
        throw new Error(data.detail || `HTTP ${resp.status}`)
      }
      const result = await resp.json()
      setStatus(
        `Signature verified: ${result.signature_verified}, Status: ${result.status}` +
          (result.reason ? ` (${result.reason})` : ''),
      )
      setAuthz(null)
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e))
      setStatus('')
    }
  }

  return (
    <section className="bg-white rounded-lg shadow p-4">
      <h2 className="text-sm font-medium text-gray-600 mb-2">Approve Transaction</h2>
      <p className="text-xs text-gray-500 mb-3">
        Enter an authorization ID to view and approve the exact-payload transaction.
      </p>
      <div className="flex gap-2 mb-3">
        <input
          type="text"
          value={authzId}
          onChange={(e) => setAuthzId(e.target.value)}
          placeholder="Authorization ID"
          className="flex-1 border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
        <button
          onClick={fetchAuthz}
          disabled={!authzId.trim()}
          className="bg-gray-600 text-white rounded-lg px-4 py-2 text-sm font-medium hover:bg-gray-700 disabled:opacity-50"
        >
          Fetch
        </button>
      </div>

      {authz && (
        <div className="border rounded p-3 bg-gray-50 space-y-1 text-sm">
          <p>
            <span className="text-gray-500">Operation:</span> {authz.operation}
          </p>
          <p>
            <span className="text-gray-500">Status:</span> {authz.status}
          </p>
          <p>
            <span className="text-gray-500">Bundle:</span> {authz.bundle_id}
          </p>
          <p className="break-all">
            <span className="text-gray-500">Hash:</span> {authz.envelope_hash}
          </p>
          <p>
            <span className="text-gray-500">Issued:</span> {authz.issued_at}
          </p>
          <p>
            <span className="text-gray-500">Expires:</span> {authz.expires_at}
          </p>
          <button
            onClick={approve}
            className="mt-2 w-full bg-green-600 text-white rounded-lg px-4 py-2 text-sm font-medium hover:bg-green-700"
          >
            Approve with WebAuthn
          </button>
        </div>
      )}

      {status && <p className="mt-2 text-sm text-blue-600">{status}</p>}
      {error && <p className="mt-2 text-sm text-red-600">{error}</p>}
    </section>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { Chat } from './components/Chat'
import { Confirmation } from './components/Confirmation'
import { Enroll, SignIn } from './components/Auth'
import { Approve } from './components/Approve'

export function App() {
  const [gatewayHealth, setGatewayHealth] = useState<string>('checking…')

  const checkHealth = useCallback(async () => {
    try {
      const res = await fetch('/api/gateway/health')
      if (res.ok) {
        const data = await res.json()
        setGatewayHealth(`${data.service}: ${data.status}`)
      } else {
        setGatewayHealth(`HTTP ${res.status}`)
      }
    } catch {
      setGatewayHealth('unreachable')
    }
  }, [])

  useEffect(() => {
    void checkHealth()
  }, [checkHealth])

  return (
    <div className="min-h-screen bg-gray-50">
      <header className="bg-blue-700 text-white px-4 py-3 shadow">
        <h1 className="text-lg font-semibold">DCTA — Direct Conversational Transaction Agent</h1>
        <p className="text-sm text-blue-100">Gateway: {gatewayHealth}</p>
      </header>
      <main className="max-w-2xl mx-auto p-4 space-y-4">
        <Enroll />
        <SignIn />
        <Approve />
        <Chat />
        <Confirmation />
      </main>
    </div>
  )
}

